package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.jsoup.helper.Validate;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class XmlDeclaration_getWholeDeclaration_TriageGen2Test {

    /**
     * Helper method to inject attributes into the private field of XmlDeclaration
     * since the provided constructor doesn't show a way to set attributes directly.
     */
    private void setAttributes(XmlDeclaration decl, Map<String, String> attributes) throws Exception {
        Field field = XmlDeclaration.class.getDeclaredField("attributes");
        field.setAccessible(true);
        field.set(decl, attributes);
    }

    @Test
    public void testGetWholeDeclaration_NameIsNotXml() {
        XmlDeclaration decl = new XmlDeclaration("html", "http://example.com", false);
        // Even if attributes size > 1, if name != "xml", it returns name
        assertEquals("html", decl.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_XmlWithOnlyOneAttribute() {
        XmlDeclaration decl = new XmlDeclaration("xml", "http://example.com", false);
        Map<String, String> attributes = new HashMap<>();
        attributes.put("version", "1.0");
        setAttributes(decl, attributes);

        // if(decl.equals("xml") && attributes.size() > 1) -> size is 1, so returns name
        assertEquals("xml", decl.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_XmlWithVersionAndEncoding() throws Exception {
        XmlDeclaration decl = new XmlDeclaration("xml", "http://example.com", false);
        Map<String, String> attributes = new HashMap<>();
        attributes.put("version", "1.0");
        attributes.put("encoding", "UTF-8");
        setAttributes(decl, attributes);

        // name is xml, size is 2. version and encoding are present.
        String expected = "xml version=\"1.0\" encoding=\"UTF-8\"";
        assertEquals(expected, decl.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_XmlWithVersionOnly() throws Exception {
        XmlDeclaration decl = new XmlDeclaration("xml", "http://example.com", false);
        Map<String, String> attributes = new HashMap<>();
        attributes.put("version", "1.0");
        attributes.put("other", "stuff"); // ensure size > 1
        setAttributes(decl, attributes);

        // encoding is null
        String expected = "xml version=\"1.0\"";
        assertEquals(expected, decl.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_XmlWithEncodingOnly() throws Exception {
        XmlDeclaration decl = new XmlDeclaration("xml", "http://example.com", false);
        Map<String, String> attributes = new HashMap<>();
        attributes.put("encoding", "UTF-8");
        attributes.put("other", "stuff"); // ensure size > 1
        setAttributes(decl, attributes);

        // version is null
        String expected = "xml encoding=\"UTF-8\"";
        assertEquals(expected, decl.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_XmlWithAttributesButNullValues() throws Exception {
        XmlDeclaration decl = new XmlDeclaration("xml", "http://example.com", false);
        Map<String, String> attributes = new HashMap<>();
        attributes.put("version", null);
        attributes.put("encoding", null);
        attributes.put("extra", "to_ensure_size_gt_1");
        setAttributes(decl, attributes);

        // name is xml, size > 1, but both version and encoding are null
        assertEquals("xml", decl.getWholeDeclaration());
    }
}
